// Package pinyindata maps CJK unified ideographs (U+4E00..U+9FFF) to a
// toneless pinyin reading, used only to turn a Chinese bot name into handle
// letters (v0.5.4). The table is generated by scripts/gen-pinyin.py from
// pypinyin 0.53.0 (MIT License, Copyright (c) 2016 mozillazg, 闲耘), keeping
// the first (most common) reading of each character. pypinyin's readings come
// from the Unicode Unihan database and its own corrections; its license is in
// LICENSE-pypinyin.txt and embedded as License. It is not a full
// transliterator: polyphonic characters always use that one reading.
package pinyindata

import (
	_ "embed"
	"encoding/binary"
	"strings"
	"sync"
)

const lo, hi = 0x4E00, 0x9FFF

// License is pypinyin's MIT license, shipped with the table it came from.
//
//go:embed LICENSE-pypinyin.txt
var License string

//go:embed syllables.txt
var syllablesTxt string

//go:embed table.bin
var table []byte

var (
	once      sync.Once
	syllables []string
)

// Lookup returns the toneless pinyin of r ("ü" written "v"), or "" when r is
// not in the table.
func Lookup(r rune) string {
	if r < lo || r > hi {
		return ""
	}
	once.Do(func() { syllables = strings.Fields(syllablesTxt) })
	i := int(r-lo) * 2
	if i+1 >= len(table) {
		return ""
	}
	n := int(binary.LittleEndian.Uint16(table[i:]))
	if n == 0 || n > len(syllables) {
		return ""
	}
	return syllables[n-1]
}
